package biliapi

import (
	"encoding/base64"
	"encoding/json"
	"github.com/avast/retry-go/v4"
	"github.com/xbclub/BilibiliDanmuRobot-Core/entity"
	"github.com/xbclub/BilibiliDanmuRobot-Core/webprofile"
	"github.com/zeromicro/go-zero/core/logx"
	"time"
)

func GetUserInfo() (userinfo *entity.UserinfoLite) {
	userinfo = new(entity.UserinfoLite)
	r, ok := fetchNav()
	if !ok {
		return userinfo
	}
	if r.Code == -412 {
		// 启动时已补齐仍 412：指纹可能已失效，强制刷新后重试一次
		logx.Info("请求被风控(412)，强制刷新 buvid 设备指纹后重试")
		refreshBuvid()
		if r, ok = fetchNav(); !ok {
			return userinfo
		}
	}
	// 登录状态以 data.isLogin 为准，未登录时接口返回 code=-101；重试后仍 412 会落到这里
	if !r.Data.IsLogin {
		logx.Infof("用户未登录 code:%v", r.Code)
		return userinfo
	}
	if resps, err := cli.R().
		SetHeader("user-agent", userAgent).
		SetHeader("cookie", CookieStr).
		Get(r.Data.Face); err != nil {
		userinfo.Avactor = "data:image/gif;base64,"
	} else {
		userinfo.Avactor = "data:image/gif;base64," + base64.StdEncoding.EncodeToString(resps.Body())
	}
	userinfo.Islogin = true
	userinfo.Username = r.Data.Uname
	userinfo.Uid = r.Data.Mid
	return userinfo
}

func fetchNav() (*entity.UserInfo, bool) {
	r := &entity.UserInfo{}
	err := retry.Do(func() error {
		resp, err := getUserInfoByGOZero()
		if err != nil {
			return err
		}
		if err := json.Unmarshal(resp, r); err != nil {
			logx.Error("Unmarshal失败：", err, "body:", string(resp))
			return err
		}
		return nil
	}, retry.Attempts(3), retry.Delay(1*time.Second))
	if err != nil {
		logx.Error(err)
		return nil, false
	}
	return r, true
}

// ensureBuvid 加载本地 cookie 后调用：若缺少 buvid3/buvid4 设备指纹则主动获取补齐，
// 避免后续所有请求被风控拦截(-412)，参见 bilibili-API-collect docs/misc/buvid3_4.md
func ensureBuvid() {
	_, has3 := CookieList["buvid3"]
	_, has4 := CookieList["buvid4"]
	if has3 && has4 {
		return
	}
	spi, err := getSPI()
	if err != nil {
		logx.Error(err)
		return
	}
	addCookieIfMissing("buvid3", spi.Data.B3)
	addCookieIfMissing("buvid4", spi.Data.B4)
}

// refreshBuvid 强制刷新 buvid3/buvid4 并覆盖已有值，
// 用于启动补齐后仍被风控(-412)时指纹可能已失效的场景
func refreshBuvid() {
	spi, err := getSPI()
	if err != nil {
		logx.Error(err)
		return
	}
	AddCookie("buvid3", spi.Data.B3)
	AddCookie("buvid4", spi.Data.B4)
}

func getSPI() (*entity.SPIInfo, error) {
	spiInfo := new(entity.SPIInfo)
	err := retry.Do(func() error {
		resp, err := cli.R().
			SetHeaders(webprofile.MainHeaders()).
			Get("https://api.bilibili.com/x/frontend/finger/spi")
		if err != nil {
			return err
		}
		if err := json.Unmarshal(resp.Body(), spiInfo); err != nil {
			logx.Error("Unmarshal失败：", err, "body:", string(resp.Body()))
			return err
		}
		return nil
	}, retry.Attempts(3), retry.Delay(1*time.Second))
	if err != nil {
		return nil, err
	}
	return spiInfo, nil
}

// addCookieIfMissing 追加一个 cookie 字段（已存在则不覆盖），与扫码登录时写 cookie 的方式一致
func addCookieIfMissing(key, value string) {
	if value == "" {
		return
	}
	if _, ok := CookieList[key]; ok {
		return
	}
	AddCookie(key, value)
}

func getUserInfoByGOZero() ([]byte, error) {
	resp, err := cli.R().
		SetHeaders(webprofile.MainHeaders()).
		SetHeader("Cookie", CookieStr).
		Get("https://api.bilibili.com/x/web-interface/nav")
	if err != nil {
		return nil, err
	}
	return resp.Body(), nil
}
